css:
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.checkout-title {
  margin-block: 0 var(--va-space-6, 1.5rem);
}

.checkout-footer {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(16rem, auto);
  gap: var(--va-space-6, 1.5rem);
  align-items: end;
  padding: var(--va-space-6, 1.5rem);
  border-block-start: 1px solid var(--va-color-border, currentColor);
}

.checkout-coupon {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--va-space-3, 0.75rem);
}

.checkout-coupon va-text-field {
  flex: 1 1 14rem;
}

/* Line the button up with the input rather than the label above it. */
.checkout-coupon va-button {
  margin-block-start: 1.75rem;
}

.checkout-summary {
  margin: 0;
  display: grid;
  gap: var(--va-space-2, 0.5rem);
}

.checkout-summary-row {
  display: flex;
  justify-content: space-between;
  gap: var(--va-space-6, 1.5rem);
}

.checkout-summary-row dt,
.checkout-summary-row dd {
  margin: 0;
}

.checkout-summary-row dd {
  font-variant-numeric: tabular-nums;
}

.checkout-summary-total {
  padding-block-start: var(--va-space-2, 0.5rem);
  border-block-start: 1px solid var(--va-color-border, currentColor);
  font-weight: 700;
  font-size: 1.125em;
}

.checkout-pay {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--va-space-4, 1rem);
}

.checkout-status {
  margin: 0;
  color: var(--va-color-text-muted, inherit);
}

@media (max-width: 40rem) {
  .checkout-footer {
    grid-template-columns: 1fr;
  }

  .checkout-pay {
    justify-content: stretch;
  }

  .checkout-pay va-button {
    flex: 1 1 100%;
  }
}
